const leaderRgb:Record<string,[number,number,number]>={Red:[190,43,47],Green:[14,139,88],Blue:[35,100,174],Purple:[116,59,155],Black:[74,80,93],Yellow:[191,142,27]};
const cardColours=(colour:string|undefined)=>Object.keys(leaderRgb).filter(name=>new RegExp(`\\b${name}\\b`,'i').test(colour??''));
const matchesLeaderColours=(card:Card,leader:Card|undefined)=>{const leaderColours=cardColours(leader?.color),colours=cardColours(card.color);return colours.length>0&&colours.every(colour=>leaderColours.includes(colour));};
const buildLeaderDeck=(pool:GameCard[],leader:GameCard|undefined)=>{if(!leader)return [];const leaderTraits=new Set(leader.traits.map(trait=>trait.toLowerCase()));const legal=pool.filter(card=>['Character','Event','Stage'].includes(String(card.type))&&matchesLeaderColours(card,leader));const ranked=[...legal].sort((left,right)=>{const leftMatch=left.traits.some(trait=>leaderTraits.has(trait.toLowerCase()))?1:0,rightMatch=right.traits.some(trait=>leaderTraits.has(trait.toLowerCase()))?1:0;return rightMatch-leftMatch||left.cost-right.cost||left.code.localeCompare(right.code)});const copies=ranked.flatMap(card=>Array.from({length:4},(_,copy)=>copy?{...card,id:`${card.id}:copy-${copy}`} as GameCard:card));return copies.slice(0,50)};
const shuffle=<T,>(items:T[])=>{const result=[...items];for(let index=result.length-1;index>0;index--){const target=Math.floor(Math.random()*(index+1));[result[index],result[target]]=[result[target],result[index]]}return result};
function matTones(color:string|undefined,fallback:[number,number,number],seed=''):React.CSSProperties{
 const tones=Object.keys(leaderRgb).filter(colour=>new RegExp(`\\b${colour}\\b`,'i').test(color??'')).map(colour=>leaderRgb[colour]);
 const [first=fallback,second=first]=tones;
 const hash=[...(color??''),...seed].reduce((total,char)=>(total*31+char.charCodeAt(0))>>>0,7);
 const point=(offset:number)=>`${18+((hash>>>offset)%60)}% ${16+((hash>>>(offset+5))%64)}%`;
 return {'--leader-tint-a':`rgb(${first.join(',')})`,'--leader-tint-b':`rgb(${second.join(',')})`,'--leader-gradient-a-position':point(0),'--leader-gradient-b-position':point(11)} as React.CSSProperties;
}
function matMarks(seed=''){
 const hash=[...seed].reduce((total,char)=>(total*33+char.charCodeAt(0))>>>0,5381);
 const regions:[[number,number],[number,number],[number,number]]=[[16,20],[82,28],[48,80]];
 return regions.map(([x,y],index)=>{const value=(hash>>>((index*7)%20))+(index*173);return {'--mat-mark-x':`${x-7+(value%15)}%`,'--mat-mark-y':`${y-6+((value>>>4)%13)}%`,'--mat-mark-size':`${38+((value>>>8)%18)}px`,'--mat-mark-rotate':`${-38+((value>>>12)%76)}deg`} as React.CSSProperties});
}
function Back({count,life=false,don=false}:{count?:number;life?:boolean;don?:boolean}){return <div className={`play-back ${life?'life-back':''} ${don?'don-back':''}`}><img src={don?playAssets.donBack:playAssets.cardBack} alt=""/>{count!==undefined&&<span>{count}</span>}</div>}
function DealFace({kind,card}:{kind:'card'|'life'|'don';card?:Card}){if(kind==='life')return <Back life/>;const image=card?cardImageUrl(card):undefined;return image?<img className="deal-face-art" src={image} alt="" loading="eager"/>:<Back don={kind==='don'}/>}
function ShowdownEffect({card}:{card:Card}){return <div className="showdown-effect"><EffectText text={card.effect}/></div>}
const dicePips:Record<number,number[]>={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]};
function Dice({value,opponent=false,label}:{value:number;opponent?:boolean;label?:string}){const pips=dicePips[value]??dicePips[1];return <span className={`die ${opponent?'opponent':''}`} aria-label={label}>{Array.from({length:9},(_,index)=><i className={pips.includes(index)?'pip':''} key={index}/>)}</span>}
