   {mulliganFlights.map(flight=><span className={`mulligan-flight ${mulliganStage}`} key={flight.id} aria-hidden="true" style={{'--mulligan-x':`${flight.fromX}px`,'--mulligan-y':`${flight.fromY}px`,'--mulligan-travel-x':`${flight.deltaX}px`,'--mulligan-travel-y':`${flight.deltaY}px`,'--mulligan-delay':`${flight.delay}ms`,'--mulligan-width':`${flight.width}px`,'--mulligan-height':`${flight.height}px`,'--mulligan-from-scale':flight.fromScale} as React.CSSProperties}>{mulliganStage==='return'?<span className="mulligan-return-card"><span className="mulligan-return-front"><CardArt card={flight.card} small/></span><span className="mulligan-return-back"><Back/></span></span>:<CardArt card={flight.card} small/>}</span>)}
